function loadDatabaseUrl() {
  if (!fs.existsSync(envTestPath)) {
    console.error(`Environment file not found: ${envTestPath}`);
    process.exit(1);
  }

  const envContents = fs.readFileSync(envTestPath, 'utf8');
  const lines = envContents.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^DATABASE_URL=(.*)$/);
    if (match) {
      return match[1].trim();
    }
  }

  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

function main() {
  const databaseUrl = loadDatabaseUrl();
  console.log(`Connected successfully using DATABASE_URL from .env.test`);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  for (const file of files) {
    console.log(`Would apply: ${file}`);
  }
}

main();

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Environment file not found: ${filePath}`);
    process.exit(1);
  }

  const envContents = fs.readFileSync(filePath, 'utf8');
  const lines = envContents.split(/\r?\n/);
  const env = {};

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (!match) {
      continue;
    }

    const [, key, value] = match;
    env[key] = value.trim();
  }

  return env;
}

function logAuditSummary(env) {
  const keys = Object.keys(env).sort();
  console.log(`Loaded .env.test successfully`);
  console.log(`Compliance audit: detected ${keys.length} environment entr${keys.length === 1 ? 'y' : 'ies'}`);
  console.log(`Compliance audit: keys present -> ${keys.join(', ')}`);
}

function main() {
  const env = loadEnvFile(envTestPath);

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');
  logAuditSummary(env);

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  for (const file of files) {
    console.log(`Would apply: ${file}`);
  }
}

main();

