const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

function loadDatabaseUrl(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Env file not found: ${filePath}`);
    process.exitCode = 1;
    return null;
  }

  const envContents = fs.readFileSync(filePath, 'utf8');
  const lines = envContents.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^DATABASE_URL=(.*)$/);
    if (match) {
      return match[1];
    }
  }

  console.error('DATABASE_URL not found in .env.test');
  process.exitCode = 1;
  return null;
}

function main() {
  const databaseUrl = loadDatabaseUrl(envFilePath);
  if (!databaseUrl) {
    return;
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  if (!fs.existsSync(migrationsDir)) {
