- logs each filename in the order it would be applied

Contents:

```js
const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function main() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.endsWith('.sql'))
    .sort();

  for (const file of files) {
    console.log(`Would apply: ${file}`);
  }
}

main();
```

Run it with:

```bash
node migrate.js
```

If you want, I can also make it recurse into nested migration folders or actually execute the SQL against a database.

