const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envTestPath = path.join(__dirname, '.env.test');

function loadDatabaseUrl(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    console.error(`Environment file not found: ${envFilePath}`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const lines = envContent.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^DATABASE_URL=(.*)$/);
    if (match) {
      return match[1].trim().replace(/^['"]|['"]$/g, '');
    }
  }

  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exit(1);
  }

  return fs
    .readdirSync(dir)
    .filter((file) => file.endsWith('.sql'))
    .sort();
}

function main() {
  const databaseUrl = loadDatabaseUrl(envTestPath);
  console.log(`Connected successfully using DATABASE_URL from .env.test: ${databaseUrl}`);

  const migrationFiles = getMigrationFiles(migrationsDir);

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  for (const file of migrationFiles) {
    const filePath = path.join(migrationsDir, file);
    const sql = fs.readFileSync(filePath, 'utf8');

    if (sql.trim()) {
      console.log(`Would apply: ${file}`);
    } else {
      console.log(`Skipping empty migration: ${file}`);
    }
  }
}

main();
